import {movePicker,selectCanonicalMove,moveDetails} from './slot-moves.mjs';
import {ITEMS,heldItems,equipSlot} from './model.mjs';
import {MOVES} from './combat-moves.mjs';
import {moveData,describeMove} from './combat-rules.mjs';
import {arenaCooldown} from './move-timing.mjs';
import {profile,level,learnable,equippedMoves,setMoves,STRUGGLE} from './training.mjs';
import {TYPE_NAMES} from './art.mjs';
export function moveCard(raw,compact=false){const m=moveData(raw);if(m.empty)return '<p>Choisis une capacité apprenable.</p>';return `<div class="move-facts"><span class="move-type type-${m.type}">${TYPE_NAMES[m.type]||m.type}</span><span>${m.status?'Statut':m.special?'Spéciale':'Physique'}</span><span>Puissance <b>${m.power||'—'}</b></span><span>${m.pp} PP · ${m.alwaysHit?'Ne rate pas':(m.accuracy??'—')+' %'}</span><span>Recharge arène <b>${arenaCooldown(m)} s</b></span></div>${compact?'':`<p class="move-effects">${describeMove(m)||'Inflige des dégâts à la cible.'}</p>${m.realtimeSupported===false?'<p class="move-mode-note">Combat au tour par tour uniquement : cet effet ne possède pas d’adaptation en temps réel.</p>':''}`}`}
export function equipmentSlots(g,key){const items=heldItems(g.state,key);return `<header><span class="eyebrow">${items.length} / 3 OBJETS</span><h3>Ses objets équipés</h3><p>Clique un emplacement pour choisir ou remplacer son objet. Trois types différents maximum.</p></header><div class="equipment-slots">${[0,1,2].map(slot=>{const i=items.find(i=>i.slot===slot);return `<article class="${i?'':'empty'}"><button class="slot-choice" data-act="lab-pick-item" data-slot="${slot}"><small>EMPLACEMENT ${slot+1}</small>${i?`<img src="assets/items/${i.key}.png" alt=""><b>${i.name}</b><p>${i.desc}</p>`:'<i>＋</i><b>Choisir un objet</b>'}</button>${i?`<button class="text-button" data-act="lab-unequip" data-uid="${i.uid}">Retirer</button>`:''}</article>`}).join('')}</div><p class="sheet-note">Remplacer ou retirer un objet le conserve dans le sac.</p>`}
export function moveSlots(g,key){const d=g.poke(key),p=profile(g.state,key),moves=equippedMoves(d,p);return `<header><span class="eyebrow">${g.state.materials.heartScale} ÉCAILLES CŒUR</span><h3>Ses quatre capacités</h3><p>Clique une capacité pour la remplacer. Une écaille cœur par changement ; une CT pour un premier apprentissage compatible. Les cases libres ne sont pas remplacées par Lutte.</p></header>${p.moveReviewNotice?'<p class="sheet-note move-review-notice">Les anciennes capacités invalides ont été retirées. Tes niveaux, statistiques et objets sont conservés. Choisis les nouvelles capacités de ces emplacements.</p>':''}<div class="move-slots">${moves.map((m,slot)=>`<article class="move-option"><button class="move-slot" data-act="lab-pick-move" data-slot="${slot}"><small>CAPACITÉ ${slot+1} · MODIFIER ↗</small><h4>${m.name}</h4>${moveCard(m)}</button>${moveDetails(g,m)}</article>`).join('')}</div><p class="sheet-note">La recharge indiquée concerne l’Arène 2D. En combat classique, chaque capacité utilise un tour et ses PP.</p>`}
export function pickerPanel(lab){const g=lab.g,key=lab.key,picker=lab.picker,slot=picker.slot,p=profile(g.state,key),d=g.poke(key);if(picker.kind==='item'){const worn=heldItems(g.state,key);return `<header><span class="eyebrow">EMPLACEMENT ${slot+1}</span><h3>Choisir son objet</h3><button data-act="lab-picker-back">← Ses objets</button></header><div class="visual-picker">${ITEMS.map(item=>{const instances=g.state.inventory.filter(i=>i.key===item.key);if(!instances.length)return '';const owner=uid=>g.state.roster.find(k=>heldItems(g.state,k).some(i=>i.uid===uid)),free=instances.filter(i=>!owner(i.uid)),uid=free[0]?.uid||instances.find(i=>owner(i.uid)!==key)?.uid||instances[0].uid,who=owner(uid),disabled=worn.some(i=>i.slot!==slot&&i.key===item.key)||worn.some(i=>i.slot===slot&&i.uid===uid);return `<button class="visual-item ${item.rarity}" data-act="lab-slot-item" data-uid="${uid}" data-slot="${slot}" ${disabled?'disabled':''}><img src="assets/items/${item.key}.png" alt=""><div><b>${item.name}</b><p>${item.desc}</p><small>×${instances.length} au total · ${free.length} disponible${free.length>1?'s':''}</small><small>${disabled?'Déjà équipé sur ce Pokémon':who?'Déplacer depuis '+g.poke(who).name:'Équiper cet exemplaire'}</small></div></button>`}).join('')||'<p>Ton sac est vide. Explore la survie ou visite la boutique.</p>'}</div>`}
 return movePicker(lab,moveCard)}
export const selectMove=selectCanonicalMove;
export function pickerAction(lab,kind,d){const g=lab.g;if(kind==='lab-pick-item'||kind==='lab-pick-move'){lab.picker={kind:kind.endsWith('item')?'item':'move',slot:+d.slot};lab.open(lab.key);return true}if(kind==='lab-picker-back'){lab.picker=null;lab.open(lab.key);return true}if(kind==='lab-slot-item'||kind==='lab-slot-move'){const ok=kind.endsWith('item')?equipSlot(g.state,lab.key,+d.slot,d.uid):selectMove(g,lab.key,+d.slot,+d.id);if(ok){lab.picker=null;g.save();g.render();lab.open(lab.key)}else g.toast('Ce choix n’est plus disponible. Vérifie les objets et les capacités équipés.');return true}return false}
